function drawText(g, str, x, y, opts) {
    var t = g.text(str).attr({
        x: x, y: y,
        'text-anchor': opts.anchor || 'middle',
        'dominant-baseline': opts.baseline || 'central',
        fill: opts.color || '#000',
        'font-family': 'sans-serif',
        'font-size': opts.size || 14
    });
    if(opts.weight) t.attr({'font-weight': opts.weight});
    return t;
}

function drawSpecies(g, cx, cy, type) {
    var s = g.group();
    // Central CH
    drawText(s, "CH", cx, cy, {});
    // Methyl
    s.line(cx, cy+10, cx, cy+22).stroke({width:1, color:'#000'});
    drawText(s, "CH", cx, cy+32, {});
    drawText(s, "3", cx+12, cy+36, {size:10});

    // Left group
    s.line(cx-14, cy, cx-25, cy).stroke({width:1, color:'#000'});
    if(type === 'anion') {
        drawText(s, "H", cx-48, cy, {color:'#00a8cc'});
        drawText(s, "2", cx-41, cy+4, {color:'#00a8cc', size:10});
        drawText(s, "N", cx-33, cy, {color:'#00a8cc'});
    } else {
        drawText(s, "H", cx-52, cy, {color:'#d81b60'});
        drawText(s, "3", cx-44, cy+4, {color:'#d81b60', size:10});
        drawText(s, "N", cx-35, cy, {color:'#d81b60'});
        drawText(s, "+", cx-27, cy-6, {color:'#d81b60', size:10});
    }

    // Right group
    s.line(cx+14, cy, cx+25, cy).stroke({width:1, color:'#000'});
    drawText(s, "C", cx+33, cy, {});
    // =O
    s.line(cx+30, cy-10, cx+30, cy-22).stroke({width:1, color:'#000'});
    s.line(cx+36, cy-10, cx+36, cy-22).stroke({width:1, color:'#000'});
    drawText(s, "O", cx+33, cy-32, {});

    // -OH / -O-
    s.line(cx+41, cy, cx+50, cy).stroke({width:1, color:'#000'});
    if(type === 'cation') {
        drawText(s, "OH", cx+62, cy, {});
    } else {
        drawText(s, "O", cx+58, cy, {});
        drawText(s, "–", cx+66, cy-4, {size:12, weight:'bold'});
    }
    return s;
}

function drawBracketed(g, cx, cy, type1, type2) {
    var grp = g.group();
    var left, right;
    var h = 45;
    if(type2) {
        drawSpecies(grp, cx - 80, cy, type1);
        drawText(grp, "+", cx, cy, {size:16});
        drawSpecies(grp, cx + 80, cy, type2);
        left = cx - 160;
        right = cx + 160;
    } else {
        drawSpecies(grp, cx, cy, type1);
        left = cx - 70;
        right = cx + 75;
    }
    var w = 5;
    grp.polyline([[left+w, cy-h], [left, cy-h], [left, cy+h], [left+w, cy+h]]).fill('none').stroke({width:1.5, color:'#000'});
    grp.polyline([[right-w, cy-h], [right, cy-h], [right, cy+h], [right-w, cy+h]]).fill('none').stroke({width:1.5, color:'#000'});
    return grp;
}

function drawChargeCircle(g, cx, cy, charge) {
    var color = charge > 0 ? '#d81b60' : (charge < 0 ? '#00a8cc' : '#888');
    var str = charge > 0 ? '+1' : (charge < 0 ? '–1' : '0');
    g.circle(44).center(cx, cy).fill(color).opacity(0.15).stroke({width:2, color:color});
    drawText(g, str, cx, cy, {size:20, color:color, weight:'bold'});
