function drawNetCharge(g, cx, cy, charge1, charge2) {
    var grp = g.group();
    if (charge2 !== undefined) {
        drawChargeCircle(grp, cx - 45, cy, charge1);
        drawText(grp, "+", cx, cy, {size:20, weight:'bold'});
        drawChargeCircle(grp, cx + 45, cy, charge2);
    } else {
        drawChargeCircle(grp, cx, cy, charge1);
