    var arrLen = 6;
    g.polygon([
        [x2, y2],
        [x2 - arrLen*Math.cos(angle - Math.PI/6), y2 - arrLen*Math.sin(angle - Math.PI/6)],
        [x2 - arrLen*Math.cos(angle + Math.PI/6), y2 - arrLen*Math.sin(angle + Math.PI/6)]
    ]).fill('#666');
}

function findpH(targetEq) {
    if (targetEq <= 0.05) return 0.5 + (targetEq/0.05)*1.0; 
    if (targetEq >= 1.95) return 10.5 + ((targetEq-1.95)/0.05)*1.0;
    var fn = function(pH) { return (1 / (1 + Math.pow(10, 2.34 - pH)) + 1 / (1 + Math.pow(10, 9.69 - pH))) - targetEq; };
    return findRoot(fn, 0, 14, 1e-5);
}

