    }

    // Right group
    s.line(cx+12, cy, cx+20, cy).stroke({width:1, color:'#000'});
    drawText(s, "C", cx+28, cy, {});
    // =O
    s.line(cx+26, cy-10, cx+26, cy-22).stroke({width:1, color:'#000'});
    s.line(cx+30, cy-10, cx+30, cy-22).stroke({width:1, color:'#000'});
    drawText(s, "O", cx+28, cy-32, {});

    // -OH / -O-
    s.line(cx+35, cy, cx+40, cy).stroke({width:1, color:'#000'});
    if(type === 'cation') {
        drawText(s, "OH", cx+52, cy, {});
    } else {
        drawText(s, "O", cx+48, cy, {});
        drawText(s, "–", cx+55, cy-6, {size:12, weight:'bold'});
    }
    return s;
}

function drawBracketed(g, cx, cy, type1, type2) {
    var grp = g.group();
    var left, right;
    var h = 40;
    if(type2) {
        drawSpecies(grp, cx - 65, cy, type1);
        drawText(grp, "+", cx, cy, {size:16});
        drawSpecies(grp, cx + 65, cy, type2);
        left = cx - 130;
        right = cx + 130;
    } else {
        drawSpecies(grp, cx, cy, type1);
        left = cx - 55;
        right = cx + 65;
    }
    var w = 5;
    grp.polyline([[left+w, cy-h], [left, cy-h], [left, cy+h], [left+w, cy+h]]).fill('none').stroke({width:1.5, color:'#000'});
    grp.polyline([[right-w, cy-h], [right, cy-h], [right, cy+h], [right-w, cy+h]]).fill('none').stroke({width:1.5, color:'#000'});
    return grp;
}

function drawChargeCircle(g, cx, cy, charge) {
    var color = charge > 0 ? '#d81b60' : (charge < 0 ? '#00a8cc' : '#888');
    var str = charge > 0 ? '+1' : (charge < 0 ? '–1' : '0');
    g.circle(44).center(cx, cy).fill(color).opacity(0.15).stroke({width:2, color:color});
    drawText(g, str, cx, cy, {size:20, color:color, weight:'bold'});
}

function drawNetCharge(g, cx, cy, charge1, charge2) {
    var grp = g.group();
    if (charge2 !== undefined) {
        drawChargeCircle(grp, cx - 45, cy, charge1);
        drawText(grp, "+", cx, cy, {size:20, weight:'bold'});
        drawChargeCircle(grp, cx + 45, cy, charge2);
    } else {
        drawChargeCircle(grp, cx, cy, charge1);
    }
    return grp;
}

function drawLabelWithArrow(g, text, tx, ty, px, py, align) {
    var stx = plotX(tx), sty = plotY(ty);
    var spx = plotX(px), spy = plotY(py);

    var lines = text.split('\n');
    lines.forEach((l, i) => {
        drawText(g, l, stx, sty + i*16 - (lines.length-1)*8, {size:12, anchor:align});
    });

    var dx = spx - stx, dy = spy - sty;
    var dist = Math.sqrt(dx*dx + dy*dy);
    if(dist > 25) {
        var startX = stx + (dx/dist)*25;
        var startY = sty + (dy/dist)*25;
        var endX = spx - (dx/dist)*10;
        var endY = spy - (dy/dist)*10;
        g.line(startX, startY, endX, endY).stroke({width:1, color:'#333'});
        var angle = Math.atan2(dy, dx);
        var arrLen = 6;
        g.polygon([
            [endX, endY],
            [endX - arrLen*Math.cos(angle - Math.PI/6), endY - arrLen*Math.sin(angle - Math.PI/6)],
            [endX - arrLen*Math.cos(angle + Math.PI/6), endY - arrLen*Math.sin(angle + Math.PI/6)]
        ]).fill('#333');
    }
}

function drawConnectionArrow(g, x1, y1, x2, y2) {
    g.line(x1, y1, x2, y2).stroke({width:1, color:'#666'});
    var angle = Math.atan2(y2-y1, x2-x1);
    var arrLen = 6;
    g.polygon([
        [x2, y2],
        [x2 - arrLen*Math.cos(angle - Math.PI/6), y2 - arrLen*Math.sin(angle - Math.PI/6)],
        [x2 - arrLen*Math.cos(angle + Math.PI/6), y2 - arrLen*Math.sin(angle + Math.PI/6)]
    ]).fill('#666');
}

function findpH(targetEq) {
    if (targetEq <= 0.05) return 0.5 + (targetEq/0.05)*1.0; 
    if (targetEq >= 1.95) return 10.5 + ((targetEq-1.95)/0.05)*1.0;
    var fn = function(pH) { return (1 / (1 + Math.pow(10, 2.34 - pH)) + 1 / (1 + Math.pow(10, 9.69 - pH))) - targetEq; };
    return findRoot(fn, 0, 14, 1e-5);
}

var chargeMap = { 'cation': 1, 'zwitter': 0, 'anion': -1 };
var markers = [
    {pH: 2.34, eq: 0.5, label: "pKa1 = 2.34"},
    {pH: 6.01, eq: 1.0, label: "Isoelectric\npoint = 6.01"},
    {pH: 9.69, eq: 1.5, label: "pKa2 = 9.69"}
];
var structures = [
    { eq: 0.0, pH: 0.5, cy_pH: 0.2, type1: 'cation', type2: null },
    { eq: 0.5, pH: 2.34, cy_pH: 2.8, type1: 'cation', type2: 'zwitter' },
    { eq: 1.0, pH: 6.01, cy_pH: 6.01, type1: 'zwitter', type2: null },
    { eq: 1.5, pH: 9.69, cy_pH: 9.2, type1: 'zwitter', type2: 'anion' },
    { eq: 2.0, pH: 11.5, cy_pH: 11.8, type1: 'anion', type2: null }
];

window.currentViewMode = "Chemical formulas";
window.currentEq = 0;

var movingDot = layerUi.circle(12).fill('#000').stroke({width:2, color:'#fff'});
var dottedLines = layerUi.group();
var hlLineX = dottedLines.line().stroke({width:1, color:'#888', dasharray:'4,4'});
var hlLineY = dottedLines.line().stroke({width:1, color:'#888', dasharray:'4,4'});

function renderAnnotations() {
    layerBg.clear();
    layerFg.clear();
    layerStruct.clear();

    // 1. Plot Background and Grid
    layerBg.rect(plotX(2.0) - plotX(0), plotY(0) - plotY(12))
        .move(plotX(0), plotY(12))
        .fill('#e1f5fe').opacity(0.6);
    [0, 0.5, 1.0, 1.5, 2.0].forEach(vx => {
        layerBg.line(plotX(vx), plotY(0), plotX(vx), plotY(12)).stroke({width:1, color:'#b3e5fc'});
        drawText(layerBg, vx.toFixed(1), plotX(vx), plotY(0)+18, {size:12, color:'#555'});
    });
    [0, 2, 4, 6, 8, 10, 12].forEach(vy => {
        layerBg.line(plotX(0), plotY(vy), plotX(2.0), plotY(vy)).stroke({width:1, color:'#b3e5fc'});
        drawText(layerBg, vy.toString(), plotX(0)-12, plotY(vy), {size:12, color:'#555', anchor:'end'});
    });

    // 2. Axes
    layerFg.line(plotX(0), plotY(0), plotX(2.1), plotY(0)).stroke({width:1.5, color:'#000'});
    layerFg.line(plotX(0), plotY(0), plotX(0), plotY(12.5)).stroke({width:1.5, color:'#000'});
    drawText(layerFg, "Equivalents of HO⁻", plotX(1.0), plotY(0)+40, {size:13, weight:'bold'});
    drawText(layerFg, "pH", plotX(0)-35, plotY(6), {size:13, weight:'bold'});

    // 3. Markers and Labels
    markers.forEach(m => {
        var cx = plotX(m.eq), cy = plotY(m.pH);
        layerFg.line(cx-4, cy-4, cx+4, cy+4).stroke({width:1.5, color:'#000'});
        layerFg.line(cx-4, cy+4, cx+4, cy-4).stroke({width:1.5, color:'#000'});

        var hitArea = layerFg.circle(28).center(cx, cy).fill('transparent').css('cursor', 'pointer');
        hitArea.on('click', function() {
            var tpIn = document.getElementById('titrationProgressInput');
            if(tpIn) {
                tpIn.value = m.eq;
                document.getElementById('titrationProgressVal').value = m.eq;
                update_titrationProgress(m.eq);
            }
            if(m.eq === 0.5 || m.eq === 1.5) {
                showPopup('Buffering Region', 'At ' + m.eq + ' equivalents, the pH stabilizes as the 1:1 mixture buffers against further changes.');
            } else if (m.eq === 1.0) {
                showPopup('Isoelectric Point', 'At exactly 1.0 equivalent, the steepest point represents a single dominant neutral species (zwitterion).');
            }
        });
        hitArea.on('mousemove', function(e) { showTooltip(m.label.replace('\n', ' '), e); });
        hitArea.on('mouseleave', hideTooltip);
    });

    drawLabelWithArrow(layerFg, "pKa1 = 2.34", 0.15, 3.8, 0.5, 2.34, 'middle');
    drawLabelWithArrow(layerFg, "Isoelectric\npoint = 6.01", 0.6, 7.5, 1.0, 6.01, 'middle');
    drawLabelWithArrow(layerFg, "pKa2 = 9.69", 1.1, 10.8, 1.5, 9.69, 'middle');

    // 4. Chemical Structures
    var rightBound = frame.width - frame.margin;
    var structCx = (plotX(2.1) + rightBound) / 2;
    var rightSpace = rightBound - plotX(2.1);
    var baseScale = Math.min(1.0, rightSpace / 280);
    baseScale = Math.max(0.6, baseScale);

    structures.forEach(st => {
        st.svgGroup = layerStruct.group();
        st.arrowGroup = layerStruct.group();
        st.formulaGroup = st.svgGroup.group();
        st.chargeGroup = st.svgGroup.group();

        var cy = plotY(st.cy_pH);
        drawBracketed(st.formulaGroup, 0, 0, st.type1, st.type2);
        drawNetCharge(st.chargeGroup, 0, 0, chargeMap[st.type1], st.type2 ? chargeMap[st.type2] : undefined);
        st.svgGroup.transform({translateX: structCx, translateY: cy, scale: baseScale});

        var targetX = structCx - (st.type2 ? 130 : 55) * baseScale;
        var arrowStartX = plotX(st.eq);
        if (st.eq === 0) arrowStartX = plotX(0.0) + 6;
        drawConnectionArrow(st.arrowGroup, arrowStartX, plotY(st.pH), targetX, cy);
    });

    updateViewMode();
    if (window.currentEq !== undefined) {
        update_titrationProgress(window.currentEq);
    }
}

window.update_titrationProgress = function(eqVal) {
    window.currentEq = eqVal;
    var t = findpH(eqVal);
    if(t !== null) {
        var px = plotX(eqVal);
        var py = plotY(t);
        movingDot.center(px, py);
        hlLineX.plot(px, py, px, plotY(0));
        hlLineY.plot(plotX(0), py, px, py);
    }
};

window.toggle_viewMode = function(isNetCharge) {
    window.currentViewMode = isNetCharge ? "Net charge" : "Chemical formulas";
    updateViewMode();
};

function updateViewMode() {
    var isCharge = window.currentViewMode === "Net charge";
    structures.forEach(st => {
        if(!st.formulaGroup) return;
        if(isCharge) {
            st.formulaGroup.hide();
            st.chargeGroup.show();
        } else {
            st.formulaGroup.show();
            st.chargeGroup.hide();
        }
    });
}

document.addEventListener('fig-resize', renderAnnotations);

// Demo player logic
var currentStep = 0;
var demoSteps = [
    {narration: "Before any base is added, the amino acid is fully protonated. Both the amino group and carboxyl group hold protons, yielding a molecule with a net +1 charge.", state: {titrationProgress: 0, viewMode: false}},
    {narration: "At 0.5 equivalents of base, half the carboxyl groups have lost a proton. The pH stabilizes around pKa1 (2.34) as the 1:1 mixture buffers against further changes.", state: {titrationProgress: 0.5, viewMode: false}},
    {narration: "At exactly 1.0 equivalent, all carboxyl groups are deprotonated while amino groups remain protonated. The +1 and -1 charges cancel, giving this zwitterion a net charge of zero.", state: {titrationProgress: 1.0, viewMode: true}},
    {narration: "At 1.5 equivalents, the amino group begins losing its proton. The pH again stabilizes around pKa2 (9.69) with a 1:1 mixture of the zwitterion and the fully deprotonated anion.", state: {titrationProgress: 1.5, viewMode: false}}
];

window.setStep = function(i) {
    currentStep = Math.max(0, Math.min(demoSteps.length-1, i));
    var step = demoSteps[currentStep];
    var nLabel = document.getElementById('demoNarration');
    if(nLabel) nLabel.textContent = step.narration;
    var sLabel = document.getElementById('stepLabel');
    if(sLabel) sLabel.textContent = (currentStep+1) + '/' + demoSteps.length;

    var tpIn = document.getElementById('titrationProgressInput');
    if(tpIn) tpIn.value = step.state.titrationProgress;
    var tpVal = document.getElementById('titrationProgressVal');
    if(tpVal) tpVal.value = step.state.titrationProgress;
    update_titrationProgress(step.state.titrationProgress);

    var vmIn = document.getElementById('viewModeInput');
    if(vmIn) vmIn.value = step.state.viewMode ? "Net charge" : "Chemical formulas";
    toggle_viewMode(step.state.viewMode);
};
window.nextStep = function() { setStep(currentStep + 1); };
window.prevStep = function() { setStep(currentStep - 1); };

renderAnnotations();
setStep(0);

window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The titration curve of an amino acid reveals its protonation states, showing buffering regions at its pKa values and a steep transition at its isoelectric point where it exists as a neutral zwitterion.
KEY INSIGHT (what students should walk away understanding): An amino acid's titration curve steps through its discrete pKa buffering regions, separated by a sharp vertical leap at its isoelectric point where the neutral zwitterion dominates.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The titration curve of an amino acid reveals its protonation states, showing buffering regions at its pKa values and a steep transition at its isoelectric point where it exists as a neutral zwitterion.",
  "figureType": "diagram",
  "elements": [
    "x-axis from 0.0 to 2.0, tick marks every 0.5, labeled 'Equivalents of HO-'",
    "y-axis from 0 to 12, tick marks every 2, labeled 'pH'",
    "pale blue shaded background grid for the plot area",
    "magenta S-shaped titration curve",
    "point marker 'x' at (0.5, 2.34) labeled 'pKa1 = 2.34'",
    "point marker 'x' at (1.0, 6.01) labeled 'Isoelectric point = 6.01'",
    "point marker 'x' at (1.5, 9.69) labeled 'pKa2 = 9.69'",
    "arrow pointing from pH ~1 to the 0.0 eq structure",
    "arrow pointing from pKa1 marker to the 0.5 eq structures",
    "arrow pointing from isoelectric point marker to the 1.0 eq structure",
    "arrow pointing from pKa2 marker to the 1.5 eq structures",
    "arrow pointing from pH ~11 to the 2.0 eq structure",
    "structure group 1 (0.0 eq): fully protonated cation, net +1 (H3N+ in magenta)",
    "structure group 2 (0.5 eq): bracketed pair of cation and zwitterion with a '+' sign between them",
    "structure group 3 (1.0 eq): zwitterion, net 0 (H3N+ in magenta, COO-)",
    "structure group 4 (1.5 eq): bracketed pair of zwitterion and anion with a '+' sign between them",
    "structure group 5 (2.0 eq): fully deprotonated anion, net -1 (H2N in cyan)"
  ],
  "interactions": [
    {
      "id": "titrationProgress",
      "type": "slider",
      "label": "Equivalents of HO-",
      "range": [
        0,
        2,
        0.01
      ],
      "default": 0,
      "teaches": "Adding base sweeps through the titration curve, steadily increasing the pH and shifting the amino acid from a fully protonated cation to a fully deprotonated anion."
    },
    {
      "id": "viewMode",
      "type": "toggle",
      "label": "Structure view",
      "options": [
        "Chemical formulas",
        "Net charge"
      ],
      "default": "Chemical formulas",
      "teaches": "The isoelectric zwitterion carries no overall charge because its discrete +1 (amino) and -1 (carboxyl) charges perfectly cancel each other out."
    },
    {
      "id": "highlightPoint",
      "type": "click",
      "teaches": "The buffering plateaus correspond precisely to 50:50 mixtures of protonation states, while the steepest point represents a single dominant species."
    }
  ],
  "demo_steps": [
    {
      "title": "Starting at acidic pH",
      "narration": "Before any base is added, the amino acid is fully protonated. Both the amino group and carboxyl group hold protons, yielding a molecule with a net +1 charge.",
      "state": {
        "titrationProgress": 0,
        "viewMode": "Chemical formulas"
      }
    },
    {
      "title": "First pKa: 50/50 mixture",
      "narration": "At 0.5 equivalents of base, half the carboxyl groups have lost a proton. The pH stabilizes around pKa1 (2.34) as the 1:1 mixture buffers against further changes.",
      "state": {
        "titrationProgress": 0.5,
        "viewMode": "Chemical formulas"
      }
    },
    {
      "title": "Isoelectric Point (pI)",
      "narration": "At exactly 1.0 equivalent, all carboxyl groups are deprotonated while amino groups remain protonated. The +1 and -1 charges cancel, giving this zwitterion a net charge of zero.",
      "state": {
        "titrationProgress": 1,
        "viewMode": "Net charge"
      }
    },
    {
      "title": "Second pKa: 50/50 mixture",
      "narration": "At 1.5 equivalents, the amino group begins losing its proton. The pH again stabilizes around pKa2 (9.69) with a 1:1 mixture of the zwitterion and the fully deprotonated anion.",
      "state": {
        "titrationProgress": 1.5,
        "viewMode": "Chemical formulas"
      }
    }
  ],
  "keyInsight": "An amino acid's titration curve steps through its discrete pKa buffering regions, separated by a sharp vertical leap at its isoelectric point where the neutral zwitterion dominates.",
  "reconstructionNotes": "Place the plot on the left (occupying about half the width) and the chemical structures stacked vertically on the right. Plot background should be a subtle pale blue with gridlines. The magenta curve should have two flat plateau regions centered at x=0.5 and x=1.5, connected by a near-vertical S-curve crossing x=1.0. Draw structures clearly with colored groups: H3N+ in magenta, H2N in cyan. When toggled to 'Net charge', swap the complex structural formulas for large simple text or color-coded circles showing just the net charge (+1, 0, -1) to simplify the visual."
}

The second image above is a screenshot of the PREVIOUS attempt's rendered output (not the source figure) — use it to see exactly what broke.

systemPrompt:
You are a strict critic of generated inline-interactive 2D figures (SVG.js / Chart.js / Mermaid) against the original 2D textbook figure image.
You will receive the original source figure image, the generated HTML/JavaScript code, and a rendered screenshot of the generated HTML (if screenshot capture succeeds). Start by using the screenshot to help evaluate the faithfulness of the generated figure to the source figure, listing discrepancies in the primitive elements between what you see in the source figure versus what you see in the generated figure. If the screenshot was not received, mention this in the notes.
Score the generated figure using the rubric and give feedback to improve the figure. Be critical and honest — err toward lower scores when in doubt. The default (step-0) state should read as a drop-in replacement for the static source image. Do not give credit for things that are absent or barely present. Output ONLY a valid JSON object — no explanation, no markdown, no fences.

AUTOMATED VERIFICATION ALREADY PASSED. A deterministic verifier has rendered this figure headless at multiple viewports and confirmed it runs without exceptions or page errors, produces a visible visual root (SVG, canvas, or Mermaid diagram) containing real text or graphics rather than an empty frame, and fits the viewport with no horizontal overflow and the main visual unclipped at wide widths.
Spend NO scores, failure modes, discrepancies, or action items on any of that. Focus ENTIRELY on SEMANTIC FIDELITY to the source: correct 2D structure, correct mark types, faithful composition and colors, correct and meaningful labels, meaningful and conceptually-correct interactions, and concept accuracy. Judge whether it is the *right* figure and a good teaching artifact — not whether it renders.
IMPORTANT — the 2D verifier performs NO label checks at all: no on-screen check, no size check, no overlap check. Label placement is fully IN SCOPE for you. Do flag labels that collide with each other or the artwork, escape the plot area, are clipped at the edge, or are too small to read comfortably at inline size.

SCAFFOLD CONTEXT (provided automatically — do not penalise for missing these):
- SVG.js v3, Chart.js v4, Mermaid v11 and expr-eval are preloaded; #container, window.__markRendered() and the 'fig-resize' event are pre-wired
- #ui is an auto-docking control panel; setUiLayout(...) positions it
- showPopup(...), showTooltip(...), hideTooltip() — built-in explainer and tooltip affordances
- Plotting helpers: setPlotFrame(...), plotX(...) / plotY(...) for data→pixel mapping, plotFunction(...), fillBetween(...), plotParametric(...), integrateSimpson(...), findRoot(...)
- compileExpr(...) and bindEquationInput(...) — live user-editable equation inputs
- Generated code may add controls, panels, and UI affordances as needed to support the planned interactions

DISCREPANCIES - list 0-6 visual discrepancies between the source figure and the generated figure, prioritized by impact on recognizability and concept accuracy
- Focus on: wrong mark types, missing or incorrect elements, wrong colors, missing or mislabeled annotations, broken or absent interactions
- De-prioritize: exact crop/zoom, whitespace variation, small differences in font face or padding — only flag these if they make the figure hard to recognize or misleading
- For multipanel source figures, if the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), check the HTML/JS before flagging a part as "missing" — a part hidden behind an unactivated toggle is not a discrepancy

FAILURE MODES — list any that apply (use empty array [] if none):
"Missing-Labels"          — important text annotations are absent
"Wrong-Primitives"        — incorrect geometric shapes used for the concept
"Interaction-Broken"      — interactive controls are present but non-functional
"Interaction-Missing"     — no meaningful interactions beyond pan/zoom or hover tooltips
"Scale-Wrong"             — element proportions are noticeably off
"Color-Wrong"             — colors don't match the original figure
"Hallucination"           — elements present that do not appear in the original
"Concept-Misunderstood"   — the core concept being illustrated is    misrepresented

SCORES — integer 1–5 for each field:
geometry_accuracy — Judge 2D structural fidelity against the source: axis ranges, tick marks and gridlines, the shape and trend of the data, node-and-edge topology and counts, relative proportions and layout, and line styling (dashed vs solid, stroke weight, arrowheads, fill vs outline). Flag "Wrong-Primitives" and cap the score when a major element uses the wrong mark type — e.g. a scatter drawn as a connected line, a bar chart drawn as an area, a directed edge drawn without its arrowhead, a smooth curve drawn as straight segments. This is a 2D figure: do NOT penalise the absence of depth, perspective, or a 3D vantage point.
  5 – All elements represented; plausible positions, connections, proportions
  4 – All major elements present; minor position/alignment issues
  3 – 1-2 elements missing OR noticeable spatial errors; concept still recognizable
  2 – Multiple missing elements OR major spatial errors
  1 – Unrecognizable or completely wrong topology

interactivity_usability — CRITICAL: panning or zooming the figure does NOT count as an interaction, and a hover tooltip on its own is weak. Meaningful interactions = sliders, toggles, buttons, demo-step players, equation inputs, or code-editor workbenches built by the developer, whose handlers actually redraw the figure.
  5 – All planned interactions functional and pedagogically useful; count matches figure complexity (1 deep slider is correct for a single-variable concept; 3+ expected for multi-step figures); demo steps present if the plan includes them
  4 – Most planned interactions functional; minor usability issues; pedagogical value clear
  3 – At least one meaningful interaction works; some planned interactions missing or broken; or interactions only weakly connected to the concept
  2 – Interactions exist in code but broken or no visible effect
  1 – Only pan/zoom or a bare hover tooltip present, or no interactions at all — score MUST be 1

faithfulness — Judge overall visual resemblance to the source — composition, geometry, and color scheme at a glance — rather than an exhaustive checklist of small differences. For multipanel source figures where the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), it is correct and expected for only one part to be visible in the default screenshot; check the HTML/JS for a toggle control before penalizing a currently-hidden part as missing or absent. Do not over-penalize extra elements added beyond the source (additional UI chrome, decorative touches) unless they clutter the figure or change its overall look — flag those under the Hallucination failure mode rather than cutting this score for minor additions.
  5 – Clearly recognizable as the same figure: correct geometry, colors, composition, and major labels all present
  4 – Recognizable at a glance; minor differences in color, proportion, or label placement
  3 – General idea clear but notable differences in geometry, composition, or missing elements
  2 – Hard to recognize as the same figure; significant content differences
  1 – Completely different or fabricated

label_quality — Label placement is NOT screened by the verifier for 2D figures — judge it fully. Judge CONTENT (right labels present, correct text, on the correct element, matching the source), PLACEMENT (collisions with each other or the artwork, escaping the plot area, clipping at the edge), and LEGIBILITY (comfortably readable at inline size, with a deliberate hierarchy — primary labels standing out over axis labels — matching what the source implies).
  5 – All the right labels present, correct text on the correct elements, matching the source, cleanly placed without collisions, AND sized/styled for easy legibility with a clear hierarchy matching the source
  4 – Content correct; only 1-2 minor issues (content, placement, OR sizing/hierarchy — e.g. a label slightly too small, or one mild collision)
  3 – Half of labels have issues, whether content (wrong text, wrong target, missing, unclear), placement (overlapping, escaping the plot area, clipped), or legibility (uncomfortably small, inconsistent hierarchy)
  2 – Most labels problematic — mislabeled/missing content, badly colliding, or generally too small/cluttered to read comfortably
  1 – No labels, or all wrong/mislabeled/illegible

concept_accuracy:
  5 – All concepts accurate; interactions demonstrate correct relationships; no misinformation
